from lib import *
S = SS('p1')
steps = [
    step("先看 HTTP:同样是本机回环上的 300 次小请求(响应体 200 字节),每次 requests.get 平均每个请求 0.50 ms(5 轮的中位数),用同一个 Session 是 0.33 ms,前者约是后者的 1.55 倍。两种做法交替跑,抵消机器状态的漂移。服务器记下的连接数很直接:300 次 requests.get 是 300 条连接、每条上只有 1 个请求;一个 Session 发 300 次只有 1 条连接、上面有 300 个请求。", t=tl(S(1)), done=lidx(S(1), '同一个 Session  :', '一个 Session 发 300 次'), mark=lidx(S(1), '每次 requests.get:', '300 次 requests.get'), b=bars([['每次 requests.get', 0.50, '0.50 ms'], ['同一个 Session', 0.33, '0.33 ms']], 0.6, mark=[0], done=[1]), kv=KV([['requests.get ×300', '300 条连接,每条 1 个请求'], ['Session ×300', '1 条连接,300 个请求'], ['单次耗时', '0.50 ms → 0.33 ms(1.55 倍)']], ['Session ×300'])),
    step("换成 HTTPS(本机自签名证书),每次新建连接要多做一次完整的 TLS 握手,差距明显放大:每次 requests.get 中位数 1.51 ms,Session 是 0.35 ms,是 4.34 倍。服务器 755 条连接对应 1500 个请求:每次新建的那一半(750 个请求)各占一条连接,另一半 5 个 Session 各用一条。HTTP 下一次新建连接多花约 0.17 ms,HTTPS 下多花约 1.16 ms,这个差额里 TLS 握手占了大头(我没有单独拆开计时)。", t=tl(S(2)), done=lidx(S(2), '同一个 Session  :'), mark=lidx(S(2), '每次 requests.get:', '4.34'), b=bars([['每次 requests.get', 1.51, '1.51 ms'], ['同一个 Session', 0.35, '0.35 ms']], 1.6, mark=[0], done=[1]), kv=KV([['HTTPS 新建', '1.51 ms'], ['HTTPS 复用', '0.35 ms'], ['倍数', '4.34(HTTP 下是 1.55)']], ['倍数'])),
    step("用了 Session 也不一定复用:前一个响应必须被读完或交还连接池。stream=True 并且既不读也不关,4 次请求用了 4 条连接,每条只有 1 个请求(连接还被前面没读完的响应占着);读完 r.content,4 次请求共用 1 条连接;不读直接 r.close() 也是 4 条连接——requests 的 Response.close() 在内容还没读完时会先关掉底层连接,连接就不再回到池里。", t=tl(S(3)), done=lidx(S(3), '读完 r.content'), mark=lidx(S(3), '不读也不关', '不读直接 r.close()'), b=bars([['不读也不关', 4, '4 条'], ['读完 r.content', 1, '1 条'], ['不读直接 close()', 4, '4 条']], 4, mark=[0, 2], done=[1]), kv=KV([['不读也不关', '4 条连接'], ['读完 r.content', '1 条连接,4 个请求'], ['不读 r.close()', '4 条连接']], ['不读 r.close()'])),
    step("连接什么时候被关掉,要看谁说了算:服务器每次回 Connection: close 并关闭,Session 发 5 次用了 5 条连接;客户端自己发 Connection: close 而服务器照办,也是 5 条;但如果服务器无视这个请求头、继续保持连接,Session 发 5 次仍然只有 1 条连接、上面 5 个请求。也就是说客户端发这个头只是“请求”,requests 不会因此自己关连接——是否复用取决于连接是否还开着(urllib3 取连接时会检查它是否已断开)。", t=tl(S(4)), done=lidx(S(4), '服务器无视并保持连接'), mark=lidx(S(4), '服务器每次回 Connection: close', '服务器照办'), b=bars([['服务器通知并关闭', 5, '5 条'], ['客户端请求、服务器照办', 5, '5 条'], ['客户端请求、服务器无视', 1, '1 条']], 5, mark=[0, 1], done=[2]), kv=KV([['服务器关', '每次新建连接'], ['客户端发 close', '只是请求,看服务器怎么回'], ['服务器无视', '连接继续复用']], ['客户端发 close'])),
]
A = mkartp('p1', 1, '爬虫,requests,Session,连接复用,keep-alive,TLS,Python,真实验证,动画演示',
    '在本机测试服务器上实测 requests 的连接复用:300 次 HTTP 小请求,每次 requests.get 0.50 ms、同一个 Session 0.33 ms;HTTPS 下是 1.51 ms 对 0.35 ms(4.34 倍);服务器那边记下的连接数是 300 对 1;stream=True 没读完响应、服务器回 Connection: close 时 Session 也复用不了。',
    '爬虫里最常见的优化建议是“用 Session”。这篇不停留在结论上:在本机起一个会记录连接的测试服务器,看 requests.get 和 Session 各自到底开了多少条连接、省下多少时间,再看看哪些写法会让 Session 白用。',
    [('300 对 1', '300 次请求:每次 requests.get 用 300 条连接,一个 Session 用 1 条'), ('4.34 倍', 'HTTPS 下每次新建连接与 Session 的单次耗时比(HTTP 下是 1.55 倍)'), ('4 条', 'stream=True 不读也不关时,4 次请求各用了一条连接')],
    [('HTTP:每次新建与 Session', '<p><code>requests.get</code> 每次调用在内部临时建一个 <code>Session</code>,用完就关(源码 <code>requests/api.py</code> 里就是 <code>with sessions.Session() as session</code>),所以每次调用都是一条新连接。服务器记录的结果和这一点吻合:300 次调用对应 300 条连接。同一个 Session 复用同一条连接发了 300 个请求。</p><p>回环网络的往返时间接近 0,所以这里 0.50 ms 对 0.33 ms 的差距基本只是建立连接本身的开销;真实网络上每条新连接还要多付至少一个往返,本文没有测。</p>'),
     ('HTTPS:握手的代价', '<p>HTTPS 下每次新建连接要多做 TLS 握手,单次耗时的比值从 1.55 倍拉到 4.34 倍。绝对值很小(本机回环、EC 证书),但它是每个请求都要付的固定成本。差额主要来自握手只是我的推断——没有把握手单独计时,也没有对比不同的密钥类型。</p>'),
     ('Session 白用的情形 (1):响应没读完', '<p>复用连接要求上一个响应已经被读完。<code>stream=True</code> 的响应如果既不读也不关,连接还被它占着,下一个请求只能新开;读完 <code>r.content</code> 才会把连接还回池里。不读直接 <code>r.close()</code> 也不行:<code>Response.close()</code> 在内容还没消费时先调用 <code>raw.close()</code>,底层连接被关掉,下次要重新建立。只想看响应头就丢掉的写法,会让 Session 的收益消失。</p>'),
     ('Session 白用的情形 (2):服务器不保持连接', '<p>服务器回 <code>Connection: close</code> 并关闭连接,Session 每次也要新建。客户端自己在请求里写 <code>Connection: close</code> 只是“请求服务器关闭”:服务器照办时同样是 5 次 5 条连接;服务器无视它时,Session 仍然复用同一条连接。urllib3 从池里取连接时会检查连接是否已经断开(<code>is_connection_dropped</code>),断开了就新建。</p>')],
    steps,
    [ENV_P + '。HTTP 与 HTTPS 各对比每次 requests.get 和同一个 Session,交替跑 5 轮,取每轮平均后的中位数;响应体 200 字节;HTTPS 用 openssl 生成的 EC P-256 自签名证书并让 requests 信任它;服务器是 Python 标准库的 http.server(HTTP/1.1),记录每条连接上的请求数',
     '没有验证:真实网络(有往返时间、有丢包)下的收益;把 TLS 握手单独计时;连接池大小不够时的行为(下一篇);HTTP/2;其它客户端库(aiohttp、httpx 等)的复用规则;服务器 keep-alive 超时到期后客户端的表现(见后面的文章)'],
    'Session 连接复用')
